from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _ledger(priority, tax_base):
    def rounded(n, mode):
        return (n + 5000) // 10000 if mode == "half_up" else n // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            if priority == "sequence_first":
                rank = (seq, event.get("revision", 0), pos)
            else:
                rank = (event.get("revision", 0), pos)
            if event_id not in chosen or rank > chosen[event_id][0]:
                chosen[event_id] = (rank, event)

        balances = dict(data.get("opening", {}))
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), data["rounding"])
            base = raw if tax_base == "original" else net
            tax = rounded(base * event.get("tax_bp", 0), data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    options = {}
    for name, versions in rows.items():
        options[name] = [None] + [v for v in versions
                                  if v not in blocked.get(name, [])
                                  and (name not in pins or pins[name] == v)]

    assignment = {}
    best_vector = None
    best_result = None

    def feasible():
        installed = {n for n, v in assignment.items() if v is not None}
        for name, (lo, hi) in roots.items():
            if name not in installed or not lo <= assignment[name] <= hi:
                return False

        graph = {n: [] for n in installed}
        reachable = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            if name not in installed:
                return False
            reachable.add(name)
            row = rows[name][assignment[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if (other not in installed or
                        not dep["min"] <= assignment[other] <= dep["max"]):
                    return False
                graph[name].append(other)
                pending.append(other)
        if reachable != installed:
            return False

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for other in graph[name]:
                if not visit(other):
                    return False
            state[name] = 2
            return True
        return all(visit(name) for name in installed)

    def search(i):
        nonlocal best_vector, best_result
        if i == len(names):
            if feasible():
                vector = tuple(-1 if assignment[n] is None else assignment[n]
                               for n in names)
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best_result = {n: assignment[n] for n in names
                                   if assignment[n] is not None}
            return
        name = names[i]
        for version in options[name]:
            assignment[name] = version
            search(i + 1)
        del assignment[name]

    search(0)
    if best_result is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_result}


def _jobs(data):
    from itertools import combinations

    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    if not mandatory.issubset({j["id"] for j in jobs}) or len(mandatory) > k:
        return {"error": "impossible"}
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for selected in combinations(jobs, k):
        ids = [j["id"] for j in selected]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not lo <= counts.get(group, 0) <= hi
               for group, (lo, hi) in quotas.items()):
            continue
        valid = True
        for job in selected:
            overlap = sum(other["start"] <= job["start"] < other["end"]
                          for other in selected)
            if overlap > 2:
                valid = False
                break
        if not valid:
            continue
        sorted_ids = sorted(ids)
        value = sum(j["value"] for j in selected)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    import heapq

    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits.get(source, 0)
    coupons = data["coupons"]
    start_state = (source, initial_mask, coupons)
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, coupons)]
    while queue:
        time, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], left)]
            if left:
                choices.append((max(1, edge["duration"] - edge.get("discount", 0)),
                                left - 1))
            for duration, next_left in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_left))
    return {"arrival": None}


SOLVERS = {
    "component_01": _ledger("revision_first", "original"),
    "component_02": _ledger("sequence_first", "original"),
    "component_03": _ledger("revision_first", "discounted"),
    "component_04": _ledger("sequence_first", "discounted"),
    "component_05": _ledger("revision_first", "original"),
    "component_06": _resolver,
    "component_07": _jobs,
    "component_08": _routes,
}
